<?php
require_once __DIR__ . '/../product_helpers.php'; require_admin();
$products = $pdo->query('SELECT p.*, c.name AS category_name FROM products p LEFT JOIN categories c ON c.id = p.category_id ORDER BY p.created_at DESC')->fetchAll();
$lowStockThreshold = (int)($pdo->query("SELECT setting_value FROM store_settings WHERE setting_key = 'low_stock_threshold'")->fetchColumn() ?: 5);
$pageTitle = 'Ürünler'; $current = 'products'; require __DIR__ . '/../header.php';
?>
<div class="page-heading"><div><p class="eyebrow">KATALOG</p><h1>Ürünler</h1><p class="text-secondary">Mağazanızdaki ürünleri görüntüleyin ve yönetin.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= e(app_url('admin/products/export.php')) ?>">CSV dışa aktar</a><a class="btn btn-primary" href="<?= e(app_url('admin/products/add.php')) ?>">＋ Ürün ekle</a></div></div>
<div class="content-card"><div class="card-heading"><div><h2>Ürün listesi</h2><p><?= count($products) ?> kayıt bulundu</p></div></div><div class="table-responsive"><table class="table product-table align-middle"><thead><tr><th>ÜRÜN</th><th>KATEGORİ</th><th>FİYAT</th><th>STOK</th><th>DURUM</th><th class="text-end">İŞLEMLER</th></tr></thead><tbody>
<?php foreach ($products as $product): ?><tr><td><div class="product-cell"><?php if ($product['image']): ?><img src="<?= e(product_image_url((string)$product['image'])) ?>" alt=""><?php else: ?><span class="product-placeholder">◇</span><?php endif; ?><div><strong><?= e($product['title']) ?></strong><small>#<?= (int)$product['id'] ?> · <?= e(date('d.m.Y', strtotime($product['created_at']))) ?></small></div></div></td><td><?= e($product['category_name'] ?? 'Kategorisiz') ?></td><td class="price-cell">₺<?= number_format((float)$product['price'], 2, ',', '.') ?></td><td><?php if ($product['stock_qty'] === null): ?><span class="text-secondary">Takip edilmiyor</span><?php elseif ((int)$product['stock_qty'] === 0): ?><span class="badge text-bg-danger">Tükendi</span><?php elseif ((int)$product['stock_qty'] <= $lowStockThreshold): ?><span class="badge text-bg-warning">Az kaldı: <?= (int)$product['stock_qty'] ?></span><?php else: ?><?= (int)$product['stock_qty'] ?><?php endif; ?></td><td><span class="status-badge <?= $product['is_active'] ? 'is-active' : 'is-inactive' ?>"><i></i><?= $product['is_active'] ? 'Aktif' : 'Pasif' ?></span></td><td><div class="action-buttons"><a class="icon-button" href="<?= e(app_url('admin/products/edit.php?id=' . (int)$product['id'])) ?>" title="Düzenle">✎</a><form method="post" action="<?= e(app_url('admin/products/delete.php')) ?>" onsubmit="return confirm('Bu ürünü silmek istediğinize emin misiniz?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><button class="icon-button danger" title="Sil">⌫</button></form></div></td></tr><?php endforeach; ?>
<?php if (!$products): ?><tr><td colspan="6"><div class="empty-state"><span>◇</span><strong>Henüz ürün yok</strong><p>İlk ürününüzü ekleyerek kataloğunuzu oluşturmaya başlayın.</p><a class="btn btn-primary" href="<?= e(app_url('admin/products/add.php')) ?>">Ürün ekle</a></div></td></tr><?php endif; ?></tbody></table></div></div>
<?php require __DIR__ . '/../footer.php'; ?>
